// Keep the repository guide identical to the bundled editor/MCP reference.
import { readFile, writeFile } from "node:fs/promises";

const help = JSON.parse(
  await readFile(new URL("../crates/proxy-script/help.json", import.meta.url), "utf8"),
);
const lines = [
  "# Traffic script API",
  "",
  "<!-- Generated by node scripts/script-help.mjs from crates/proxy-script/help.json. -->",
  "The same reference is available in **Automation → Scripts → Script API** and",
  "through MCP `transmog_help`. The editor supplies the [complete types](../crates/proxy-script/generated/transmog-script.d.ts).",
  "",
];
for (const section of help.sections) {
  lines.push(`## ${section.title}`, "", ...section.paragraphs.flatMap((text) => [text, ""]));
  if (section.phases.length) {
    lines.push("| Handler | Additional input | Decisions |", "| --- | --- | --- |");
    for (const phase of section.phases)
      lines.push(`| \`${phase.handler}\` | ${phase.input} | ${phase.decisions} |`);
    lines.push("");
  }
  if (section.id === "evidence")
    lines.push(help.failureCategories.map((name) => `\`${name}\``).join(", ") + ".", "");
  for (const example of section.examples) {
    lines.push(`### ${example.title}`, "", example.settings, "", "```ts", example.code, "```", "");
  }
}
lines.push("## MCP support", "", help.mcpSupport, "");
const output = lines.join("\n");
const path = new URL("../docs/scripting.md", import.meta.url);
if (process.argv.includes("--check")) {
  if ((await readFile(path, "utf8")).replaceAll("\r\n", "\n") !== output) {
    throw new Error("Script help is out of date. Run node scripts/script-help.mjs.");
  }
} else {
  await writeFile(path, output);
}
